<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TenantTermsOfUse\Domain\ValueObject\Accessor\TenantTermsOfUseAttachedAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TenantTermsOfUseAttachedAccessor trait.
 *
 * Covers null default, string/VO assignment via withAttached,
 * getAttached/attached accessors, and isAttachedChanged with/without original.
 */
class TenantTermsOfUseAttachedAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withAttached creates a new instance with the Attached set
     * from a string value, and getAttached returns the primitive string.
     */
    public function testWithAttachedFromString(): void
    {
        // Arrange
        $holder = new ImplWithTenantTermsOfUseAttachedAccessorUnitTest();

        // Act
        $result = $holder->withAttached('store://bin');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('bin', $result->getAttached());
    }
    /**
     * Asserts that withattached has access to the value object
     * from a string value, and getAttached returns the primitive string.
     */
    public function testWithAttachedFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTenantTermsOfUseAttachedAccessorUnitTest();

        // Act
        $result = $holder->withAttached('store://bin');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('bin', $result->attached()->value());
    }
    public function testChangedAttached(): void
    {
        // Arrange
        $holder = new ImplWithTenantTermsOfUseAttachedAccessorUnitTest();
        $original = $holder->withAttached('store://bin');
        $same = $holder->withAttached('store://bin');
        $modified = $holder->withAttached('store://obin');

        // Act
        $unchanged = $holder->isAttachedChanged();
        $withSame = $original->isAttachedChanged($same);
        $withDiferent = $original->isAttachedChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTenantTermsOfUseAttachedAccessorUnitTest
{
    use TenantTermsOfUseAttachedAccessor;
}
